import { loadImage } from '../assets.js';

const at = (path) => new URL(`../art/look/${path}`, import.meta.url).href;
export const LOOK_ART = Object.freeze({ floor: {}, decal: {}, prop: {}, backdrop: {} });

/** The loaded image for an art id of a kind ('floor' | 'decal' | 'prop' | 'backdrop'), or null (paint the stand-in). */
export function lookImage(kind, id) {
  const file = id && LOOK_ART[kind]?.[id];
  return file ? loadImage(at(file)) : null;
}
/** Every file this look art map names (preload). */
export const lookFiles = () => Object.values(LOOK_ART).flatMap(o => Object.values(o)).map(at);
